import { css } from "@emotion/react";
import { motion } from "motion/react";

import Section from "./Section";
import { SKILLS } from "../data/content";
import { group, rise, inView } from "../lib/motion";

const Skills = () => (
  <Section id="skills" title="기술">
    <motion.dl css={table} variants={group} {...inView}>
      {SKILLS.map((s) => (
        <motion.div key={s.group} variants={rise}>
          <dt>{s.group}</dt>
          <dd>
            {s.items.map((i) => (
              <motion.span key={i} whileHover={{ y: -2 }}>
                {i}
              </motion.span>
            ))}
          </dd>
        </motion.div>
      ))}
    </motion.dl>
  </Section>
);

export default Skills;

const table = css`
  display: grid;
  div {
    display: grid;
    grid-template-columns: 130px 1fr;
    gap: 20px;
    padding: 16px 0;
  }
  div + div {
    border-top: 1px solid #dcdcd8;
  }
  dt {
    font-weight: 600;
    padding-top: 3px;
  }
  dd {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }
  span {
    display: inline-block;
    font-size: 0.9375rem;
    font-weight: 500;
    padding: 4px 12px;
    border-radius: 999px;
    background: var(--surface);
  }
  @media (max-width: 600px) {
    div {
      grid-template-columns: 1fr;
      gap: 10px;
    }
  }
`;
