import type { MouseEvent } from "react";
import Lenis from "lenis";

let lenis: Lenis | null = null;

const prefersReducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** Lenis 시작. 모션 줄이기 설정이면 네이티브 스크롤 그대로 둔다. */
export const startSmoothScroll = () => {
  if (prefersReducedMotion()) return () => {};
  lenis = new Lenis({ autoRaf: true, lerp: 0.09, wheelMultiplier: 0.9 });
  return () => {
    lenis?.destroy();
    lenis = null;
  };
};

export const scrollToId = (id: string) => {
  const el = document.getElementById(id);
  if (!el) return;
  if (lenis) lenis.scrollTo(el, { duration: 1.4 });
  else el.scrollIntoView({ behavior: prefersReducedMotion() ? "auto" : "smooth" });
};

/** 다이얼로그가 열려 있는 동안 페이지 스크롤을 멈춘다. */
export const lockScroll = (locked: boolean) => {
  if (locked) lenis?.stop();
  else lenis?.start();
  document.documentElement.style.overflow = locked ? "hidden" : "";
};

/** <a href="#id"> 클릭을 Lenis 스크롤로 바꾼다. 스크립트가 없으면 일반 앵커로 동작. */
export const onAnchorClick = (id: string) => (e: MouseEvent) => {
  e.preventDefault();
  scrollToId(id);
};
