/** @jsxImportSource @emotion/react */
import type { ReactNode } from "react";
import { css } from "@emotion/react";
import { motion } from "motion/react";

import { EASE } from "../lib/motion";

/** 화면에 들어오면 형광펜이 왼쪽에서 오른쪽으로 그어진다 */
const Highlight = ({ children, delay = 0 }: { children: ReactNode; delay?: number }) => (
  <span css={wrap}>
    <motion.span
      aria-hidden
      css={marker}
      initial={{ scaleX: 0 }}
      whileInView={{ scaleX: 1 }}
      viewport={{ once: true, margin: "0px 0px -20% 0px" }}
      transition={{ duration: 0.7, delay, ease: EASE }}
    />
    <span css={text}>{children}</span>
  </span>
);

export default Highlight;

const wrap = css`
  position: relative;
  white-space: nowrap;
`;

const marker = css`
  position: absolute;
  left: -0.12em;
  right: -0.12em;
  bottom: 0.08em;
  height: 0.5em;
  background: var(--accent);
  opacity: 0.85;
  transform-origin: left;
  border-radius: 2px;
`;

const text = css`
  position: relative;
`;
