/** @jsxImportSource @emotion/react */
import { useEffect, useRef } from "react";
import { css } from "@emotion/react";

const GAP = 28; // 점 사이 간격(px)
const BASE_R = 1.2; // 기본 점 반지름
const HOVER_R = 3.2; // 커서 바로 아래 점 반지름
const REACH = 160; // 커서가 영향을 주는 거리
const RIPPLE_GROW = 2.2; // 가장 센 파동이 지나갈 때 점이 커지는 정도(px)

/**
 * ring: 퍼져 나가는 고리. band는 고리 두께(px).
 * glow: 제자리에서 살짝 번지는 둥근 빛. band는 시작 반지름(px).
 * speed는 퍼지는 속도(px/ms), life는 사라지기까지(ms), power는 세기(0~1).
 */
type RippleKind = { shape: "ring" | "glow"; speed: number; life: number; band: number; power: number };
const CLICK: RippleKind = { shape: "ring", speed: 0.7, life: 1500, band: 48, power: 1 };
// 드래그 자국은 고리로 만들면 같은 점을 여러 번 지나가며 깜박이므로, 지나간 자리에 번지는 빛으로 남긴다
const TRAIL: RippleKind = { shape: "glow", speed: 0.03, life: 1300, band: 44, power: 0.85 };
const TRAIL_STEP = 28; // 드래그 자국 사이 간격(px)
// 보이는 중인 자국이 잘려 나가며 툭 꺼지지 않도록 넉넉히 둔다. 빠르게 휘저어도 이 이상은 쌓이지 않는다
const MAX_RIPPLES = 90;

const smoothstep = (v: number) => v * v * (3 - 2 * v);
// 처음엔 천천히, 끝에서는 부드럽게 0이 되도록 옅어진다
const fadeOut = (age: number, life: number) => smoothstep(Math.max(0, 1 - age / life));
const DOT = [201, 201, 197]; // 기본 점 색
const ACCENT = [255, 90, 31]; // 포인트 오렌지

const mix = (a: number[], b: number[], t: number) => a.map((v, i) => Math.round(v + (b[i] - v) * t));

/**
 * 랜딩 배경의 점 격자. 평소에는 가만히 있고, 커서 주변의 점이 커지며 오렌지로 물들며,
 * 클릭하면 그 지점에서 파동이 퍼지고, 누른 채 끌면 지나간 길을 따라 작은 파동이 이어진다.
 * 부모 요소를 꽉 채운다.
 */
const DotField = () => {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    const host = canvas?.parentElement;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !host || !ctx) return;

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let width = 0;
    let height = 0;
    let frame = 0;
    let visible = true;
    // 커서 위치는 바로 따라가지 않고 살짝 늦게 따라와 부드럽게 움직인다
    const pointer = { x: -9999, y: -9999, tx: -9999, ty: -9999, strength: 0, target: 0 };
    // 클릭할 때마다, 그리고 누른 채 끄는 동안 일정 거리마다 고리 모양 파동이 하나씩 퍼진다
    let ripples: ({ x: number; y: number; start: number } & RippleKind)[] = [];
    const drag = { active: false, lastX: 0, lastY: 0 };
    const addRipple = (x: number, y: number, kind: RippleKind) => {
      ripples.push({ x, y, start: performance.now(), ...kind });
      if (ripples.length > MAX_RIPPLES) ripples.shift();
    };

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      width = host.clientWidth;
      height = host.clientHeight;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const draw = (time: number) => {
      pointer.x += (pointer.tx - pointer.x) * 0.15;
      pointer.y += (pointer.ty - pointer.y) * 0.15;
      pointer.strength += (pointer.target - pointer.strength) * 0.08;

      ctx.clearRect(0, 0, width, height);
      const offsetX = (width % GAP) / 2;
      const offsetY = (height % GAP) / 2;
      ripples = ripples.filter((rp) => time - rp.start < rp.life);

      for (let y = offsetY; y < height; y += GAP) {
        for (let x = offsetX; x < width; x += GAP) {
          const dist = Math.hypot(x - pointer.x, y - pointer.y);
          const near = Math.max(0, 1 - dist / REACH) * pointer.strength;
          // 고리가 지나가거나 빛이 번진 자리의 점일수록, 파동이 젊을수록 강하게 물든다
          let ring = 0;
          for (const rp of ripples) {
            const age = Math.max(0, time - rp.start);
            const fade = fadeOut(age, rp.life);
            const from = Math.hypot(x - rp.x, y - rp.y);
            const v =
              rp.shape === "ring"
                ? Math.max(0, 1 - Math.abs(from - age * rp.speed) / rp.band)
                : smoothstep(Math.max(0, 1 - from / (rp.band + age * rp.speed)));
            ring = Math.max(ring, v * fade * rp.power);
          }
          const t = Math.max(near, ring);
          // 커서 주변은 가까울수록 급하게, 파동은 고리를 따라 고르게 부풀어 오른다
          const r = BASE_R + Math.max((HOVER_R - BASE_R) * near * near, RIPPLE_GROW * ring);
          const [cr, cg, cb] = mix(DOT, ACCENT, t);

          ctx.beginPath();
          ctx.arc(x, y, r, 0, Math.PI * 2);
          ctx.fillStyle = `rgb(${cr}, ${cg}, ${cb})`;
          ctx.fill();
        }
      }
    };

    // 평소에는 멈춰 있고, 커서가 머물거나 파동이 퍼지는 동안에만 다시 그린다
    let running = false;
    const isSettled = () => pointer.target === 0 && pointer.strength < 0.005 && ripples.length === 0;
    const loop = (time: number) => {
      draw(time);
      if (visible && !isSettled()) {
        frame = requestAnimationFrame(loop);
      } else {
        running = false;
      }
    };
    const wake = () => {
      if (running || !visible || reduce) return;
      running = true;
      frame = requestAnimationFrame(loop);
    };

    // 배경 위에 글자가 겹쳐 있어도 반응하도록, 창 전체에서 커서를 받아 영역 안인지만 본다
    const onMove = (e: PointerEvent) => {
      if (e.pointerType !== "mouse") return;
      const rect = host.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const inside = x >= 0 && y >= 0 && x <= rect.width && y <= rect.height;
      if (!inside) {
        if (pointer.target === 1) {
          pointer.target = 0;
          wake(); // 물든 점이 서서히 빠지는 동안은 계속 그린다
        }
        return;
      }
      pointer.tx = x;
      pointer.ty = y;
      if (pointer.target === 0) {
        pointer.x = x;
        pointer.y = y;
      }
      pointer.target = 1;

      // 왼쪽 버튼을 누른 채 끌고 있으면, 마지막 자국에서 충분히 멀어질 때마다 작은 파동을 남긴다
      if (drag.active && !reduce) {
        if ((e.buttons & 1) === 0) {
          drag.active = false;
        } else if (Math.hypot(x - drag.lastX, y - drag.lastY) >= TRAIL_STEP) {
          addRipple(x, y, TRAIL);
          drag.lastX = x;
          drag.lastY = y;
        }
      }
      wake();
    };
    const onLeave = () => {
      pointer.target = 0;
      drag.active = false;
      wake();
    };
    const onDown = (e: PointerEvent) => {
      if (reduce || e.pointerType !== "mouse" || e.button !== 0) return;
      const rect = host.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      if (x < 0 || y < 0 || x > rect.width || y > rect.height) return;
      addRipple(x, y, CLICK);
      drag.active = true;
      drag.lastX = x;
      drag.lastY = y;
      wake();
    };
    const onUp = () => {
      drag.active = false;
    };

    // 화면 밖에 있을 때는 그리지 않는다
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (!visible) {
        cancelAnimationFrame(frame);
        running = false;
      } else if (!isSettled()) {
        wake();
      }
    });

    const resizeObserver = new ResizeObserver(() => {
      resize();
      draw(performance.now());
    });

    resize();
    draw(0);
    observer.observe(host);
    resizeObserver.observe(host);
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerdown", onDown, { passive: true });
    window.addEventListener("pointerup", onUp, { passive: true });
    document.documentElement.addEventListener("mouseleave", onLeave);

    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      resizeObserver.disconnect();
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointerup", onUp);
      document.documentElement.removeEventListener("mouseleave", onLeave);
    };
  }, []);

  return <canvas ref={ref} css={canvasStyle} aria-hidden />;
};

export default DotField;

const canvasStyle = css`
  position: absolute;
  inset: 0;
  pointer-events: none;
  /* 가장자리로 갈수록 점이 사라져 화면 가운데에 시선이 모인다 */
  mask-image: radial-gradient(ellipse 75% 70% at 50% 45%, #000 30%, transparent 100%);
  -webkit-mask-image: radial-gradient(ellipse 75% 70% at 50% 45%, #000 30%, transparent 100%);
`;
