/** @jsxImportSource @emotion/react */
import { useEffect, useState } from "react";
import { css } from "@emotion/react";
import { motion, useMotionValueEvent, useScroll } from "motion/react";

import { SECTIONS, column } from "./Section";
import { GITHUB } from "../data/content";
import { onAnchorClick } from "../lib/smoothScroll";

/** 화면 위쪽 1/3 지점을 지나고 있는 섹션 */
const useActiveSection = () => {
  const [active, setActive] = useState<string | null>(null);
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => entries.forEach((e) => e.isIntersecting && setActive(e.target.id)),
      { rootMargin: "-30% 0px -65% 0px" }
    );
    SECTIONS.forEach((s) => {
      const el = document.getElementById(s.id);
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, []);
  return active;
};

const Header = () => {
  const { scrollY, scrollYProgress } = useScroll();
  const [hidden, setHidden] = useState(false);
  const active = useActiveSection();

  // 내려갈 때는 숨기고, 올라갈 때 다시 보여준다
  useMotionValueEvent(scrollY, "change", (y) => {
    const prev = scrollY.getPrevious() ?? 0;
    setHidden(y > prev && y > 160);
  });

  return (
    <motion.header
      css={bar}
      animate={{ y: hidden ? "-100%" : "0%" }}
      transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
    >
      <div css={inner}>
        <a href="#home" css={name} onClick={onAnchorClick("home")}>
          심우진
        </a>
        <nav css={nav} aria-label="섹션">
          {SECTIONS.map((s) => (
            <a
              key={s.id}
              href={`#${s.id}`}
              onClick={onAnchorClick(s.id)}
              aria-current={active === s.id ? "true" : undefined}
            >
              {s.label}
              {active === s.id && <motion.span layoutId="nav-dot" css={dot} />}
            </a>
          ))}
          <a href={GITHUB} target="_blank" rel="noopener noreferrer" css={hideOnPhone}>
            GitHub
          </a>
        </nav>
      </div>
      <motion.div css={progress} style={{ scaleX: scrollYProgress }} />
    </motion.header>
  );
};

export default Header;

const bar = css`
  position: sticky;
  top: 0;
  z-index: 20;
  background: var(--bg);
`;

const inner = css`
  ${column};
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
`;

const name = css`
  font-weight: 700;
  text-decoration: none;
  letter-spacing: -0.02em;
`;

const nav = css`
  display: flex;
  gap: 20px;
  font-size: var(--step-small);
  a {
    position: relative;
    text-decoration: none;
    color: var(--muted);
    padding: 6px 0;
    transition: color 0.2s ease;
  }
  a:hover,
  a[aria-current] {
    color: var(--ink);
  }
  @media (max-width: 420px) {
    gap: 14px;
  }
`;

const dot = css`
  position: absolute;
  left: 50%;
  bottom: -4px;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  border-radius: 50%;
  background: var(--accent);
`;

const hideOnPhone = css`
  @media (max-width: 520px) {
    display: none;
  }
`;

const progress = css`
  height: 3px;
  background: var(--accent);
  transform-origin: left;
`;
