/** @jsxImportSource @emotion/react */
import { useRef } from "react";
import { css } from "@emotion/react";
import { motion, useScroll, useTransform, MotionValue } from "motion/react";

import Section from "./Section";
import Highlight from "./Highlight";
import { group, rise, inView } from "../lib/motion";

const STATEMENT = "코드를 짜기 전에 구조를 먼저, 나중에 고치기 어려운 결정일수록 더 견고히 생각합니다.";

/** 스크롤 진행에 맞춰 단어가 하나씩 진해진다 */
const Word = ({
  children,
  progress,
  range,
}: {
  children: string;
  progress: MotionValue<number>;
  range: [number, number];
}) => {
  const opacity = useTransform(progress, range, [0.2, 1]);
  return <motion.span style={{ opacity }}>{children} </motion.span>;
};

const About = () => {
  const ref = useRef<HTMLParagraphElement>(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start 0.9", "end 0.55"] });
  const words = STATEMENT.split(" ");

  return (
    <Section id="about" title="소개">
      <p ref={ref} css={statement}>
        {words.map((w, i) => (
          <Word key={i} progress={scrollYProgress} range={[i / words.length, (i + 1) / words.length]}>
            {w}
          </Word>
        ))}
      </p>
      <motion.div css={body} variants={group} {...inView}>
        <motion.p variants={rise}>
          문제를 만나면 현상보다 <Highlight>원인에 집중</Highlight>하고 해소를 위한 흐름을 고민합니다.
        </motion.p>
        <motion.p variants={rise}>
          처음 제대로 만든 웹 애플리케이션은 GOP 영상감시병으로 복무하던 때 폐쇄망 안에서 만든 상황조치도우미였습니다.
          외부 라이브러리도 인터넷도 없이 만든 그 시스템은 정식 사용 승인을 받아{" "}
          <Highlight delay={0.2}>지금도 현장에서</Highlight> 쓰이고 있습니다.
        </motion.p>
        <motion.p variants={rise}>
          필요한 것을 보고, 만들고, 해소되기까지. 이 과정의 즐거움을 알기에, 결과물이 불러오는 변화를 소중하게
          생각합니다.
        </motion.p>
      </motion.div>
    </Section>
  );
};

export default About;

const statement = css`
  font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.125rem);
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: -0.025em;
`;

const body = css`
  margin-top: 40px;
  display: grid;
  gap: 1.1em;
`;
