/** @jsxImportSource @emotion/react */
import { css } from "@emotion/react";
import { motion } from "motion/react";

import Section from "./Section";
import { COMPANIES, CareerProject } from "../data/content";
import { group, rise, inView } from "../lib/motion";
import gongkiLogo from "../assets/Images/Gongki.png";
import flowwwLogo from "../assets/Images/Flowww.png";

const LOGOS: Record<string, string> = { costar: gongkiLogo, flowww: flowwwLogo };

const Project = ({ project }: { project: CareerProject }) => (
  <motion.li variants={rise}>
    <div css={row}>
      <span css={date}>{project.period}</span>
      <div>
        <h4 css={projectTitle}>{project.title}</h4>
        <ul css={points}>
          {project.points.map((p) => (
            <li key={p.lead}>
              <strong>{p.lead}.</strong> {p.rest}
            </li>
          ))}
        </ul>
        <div css={tags}>
          {project.stack.map((s) => (
            <span key={s}>{s}</span>
          ))}
          {project.link && (
            <a href={project.link.href} target="_blank" rel="noopener noreferrer" css={link}>
              {project.link.label} ↗
            </a>
          )}
        </div>
      </div>
    </div>
  </motion.li>
);

const Career = () => (
  <Section id="career" title="경력">
    {COMPANIES.map((c) => (
      <div key={c.id} css={company}>
        <motion.div css={companyHead} variants={rise} {...inView}>
          <img src={LOGOS[c.id]} alt={`${c.name} 로고`} width={48} height={48} />
          <div>
            <h3>
              {c.role} · <span css={{ whiteSpace: "nowrap" }}>{c.name}</span>
            </h3>
            <p>
              {c.period} · {c.description}
            </p>
          </div>
        </motion.div>
        <motion.ul css={list} variants={group} {...inView}>
          {c.projects.map((p) => (
            <Project key={p.title} project={p} />
          ))}
        </motion.ul>
      </div>
    ))}
  </Section>
);

export default Career;

const company = css`
  & + & {
    margin-top: 80px;
  }
`;

const companyHead = css`
  display: flex;
  gap: 16px;
  align-items: center;
  img {
    flex: none;
    border-radius: 10px;
  }
  h3 {
    font-size: 1.375rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.3;
  }
  p {
    color: var(--muted);
    font-size: var(--step-small);
  }
`;

const list = css`
  list-style: none;
  margin: 24px -20px 0;
  display: grid;
  gap: 4px;
  /* 하나를 가리키면 나머지는 한 발 물러난다 */
  @media (hover: hover) {
    &:hover > li > div {
      opacity: 0.5;
    }
    &:hover > li:hover > div {
      opacity: 1;
      background: var(--surface);
    }
  }
  @media (max-width: 600px) {
    margin: 20px 0 0;
  }
`;

const row = css`
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 20px;
  padding: 20px;
  border-radius: 12px;
  transition:
    opacity 0.25s ease,
    background-color 0.25s ease;
  @media (max-width: 600px) {
    grid-template-columns: 1fr;
    gap: 4px;
    padding: 16px 0;
  }
`;

const date = css`
  padding-top: 3px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
`;

const projectTitle = css`
  font-size: var(--step-lead);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.35;
`;

const points = css`
  margin-top: 10px;
  display: grid;
  gap: 8px;
  padding-left: 1.1em;
  list-style: disc;
  font-size: 0.96875rem;
  li::marker {
    color: var(--accent);
  }
  strong {
    font-weight: 600;
  }
`;

const tags = css`
  margin-top: 14px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  span {
    font-size: 0.8125rem;
    font-weight: 500;
    padding: 3px 10px;
    border-radius: 999px;
    background: var(--surface-hover);
  }
`;

const link = css`
  font-size: 0.8125rem;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  /* 13px 글자는 오렌지 위 흰색으로 대비가 모자라 검정 바탕에 둔다 */
  background: var(--ink);
  color: #fff;
  text-decoration: none;
  transition: background-color 0.2s ease;
  &:hover {
    background: var(--accent);
  }
`;
