/** @jsxImportSource @emotion/react */
import { useState } from "react";
import { css } from "@emotion/react";
import { AnimatePresence, motion } from "motion/react";

import Section from "./Section";
import ProjectDialog from "./ProjectDialog";
import { SIDE_PROJECTS } from "../data/content";
import { group, rise, inView } from "../lib/motion";

const SideProjects = () => {
  const [openId, setOpenId] = useState<string | null>(null);
  const opened = SIDE_PROJECTS.find((p) => p.id === openId);

  return (
    <Section id="projects" title="사이드 프로젝트">
      <motion.ul css={list} variants={group} {...inView}>
        {SIDE_PROJECTS.map((p) => (
          <motion.li key={p.id} variants={rise}>
            <button type="button" css={row} onClick={() => setOpenId(p.id)} aria-haspopup="dialog">
              <span css={date}>{p.date}</span>
              <span>
                <strong css={title}>
                  {p.title}
                  <span css={arrow} aria-hidden>
                    →
                  </span>
                </strong>
                <span css={team}>{p.team}</span>
                <span css={summary}>{p.summary}</span>
              </span>
            </button>
          </motion.li>
        ))}
      </motion.ul>
      <AnimatePresence>{opened && <ProjectDialog project={opened} onClose={() => setOpenId(null)} />}</AnimatePresence>
    </Section>
  );
};

export default SideProjects;

const list = css`
  list-style: none;
  margin: 0 -20px;
  display: grid;
  gap: 4px;
  @media (hover: hover) {
    &:hover > li > button {
      opacity: 0.5;
    }
    &:hover > li:hover > button {
      opacity: 1;
    }
  }
  @media (max-width: 600px) {
    margin: 0;
  }
`;

const row = css`
  width: 100%;
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 20px;
  padding: 16px 20px;
  border: 0;
  border-radius: 12px;
  background: none;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.25s ease, opacity 0.25s ease;
  &:hover {
    background: var(--surface);
  }
  &:hover [aria-hidden] {
    transform: translateX(4px);
    color: var(--ink);
  }
  @media (max-width: 600px) {
    grid-template-columns: 1fr;
    gap: 2px;
    padding: 14px 0;
  }
`;

const date = css`
  padding-top: 2px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
`;

const title = css`
  font-weight: 700;
`;

const arrow = css`
  display: inline-block;
  margin-left: 6px;
  color: var(--muted);
  transition: transform 0.2s ease, color 0.2s ease;
`;

const team = css`
  margin-left: 10px;
  font-size: var(--step-small);
  color: var(--muted);
`;

const summary = css`
  display: block;
  margin-top: 4px;
  font-size: 0.9375rem;
  color: #3a3a3a;
`;
