/** @jsxImportSource @emotion/react */
import { useEffect, useRef, useState } from "react";
import { css } from "@emotion/react";
import { AnimatePresence, motion, useScroll, useTransform } from "motion/react";

import { column } from "./Section";
import DotField from "./DotField";
import CursorDot from "./CursorDot";
import { EASE } from "../lib/motion";
import { onAnchorClick } from "../lib/smoothScroll";

/** 지금 실제로 만들고 있는 것들을 다른 회사 사람도 알아듣는 말로 — 조사까지 붙여 둔다 */
const WORKS = ["디자인 시스템을", "운영 도구를", "데이터 흐름을", "함께 쓰는 컴포넌트를", "API SDK를", "현장의 화면을"];
const INTERVAL = 2600;

const toGraphemes = (text: string) =>
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? Array.from(new Intl.Segmenter("ko", { granularity: "grapheme" }).segment(text), (s) => s.segment)
    : Array.from(text);

/** 단어가 한 글자씩 아래에서 올라오며 바뀐다 */
const RotatingWord = () => {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const id = setInterval(() => setIndex((i) => (i + 1) % WORKS.length), INTERVAL);
    return () => clearInterval(id);
  }, []);

  return (
    <span css={rotator}>
      <AnimatePresence mode="wait" initial={false}>
        <motion.span key={index} css={{ display: "inline-block" }}>
          {toGraphemes(WORKS[index]).map((ch, i) => (
            <span key={i} css={charMask}>
              <motion.span
                css={{ display: "inline-block", whiteSpace: "pre" }}
                initial={{ y: "100%" }}
                animate={{ y: 0 }}
                exit={{ y: "-110%" }}
                transition={{ type: "spring", damping: 30, stiffness: 400, delay: i * 0.025 }}
              >
                {ch}
              </motion.span>
            </span>
          ))}
        </motion.span>
      </AnimatePresence>
    </span>
  );
};

const Landing = () => {
  const ref = useRef<HTMLElement>(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start start", "end start"] });
  // 스크롤하면 천천히 위로 밀려나며 흐려진다
  const y = useTransform(scrollYProgress, [0, 1], ["0%", "-30%"]);
  const opacity = useTransform(scrollYProgress, [0, 0.7], [1, 0]);

  return (
    <section id="home" ref={ref} css={landing} aria-labelledby="landing-title">
      <motion.div
        css={backdrop}
        style={{ opacity }}
        initial={{ scale: 1.04 }}
        animate={{ scale: 1 }}
        transition={{ duration: 1.6, ease: EASE }}
      >
        <DotField />
      </motion.div>
      <motion.div css={inner} style={{ y, opacity }}>
        <motion.p
          css={eyebrowless}
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, ease: EASE }}
        >
          프론트엔드 개발자 심우진
        </motion.p>

        <h1 id="landing-title" css={headline}>
          <span css={srOnly}>{`${WORKS.join(", ")} 만들고 있습니다`}</span>
          <span aria-hidden>
            {[<RotatingWord key="w" />, "만들고 있습니다"].map((line, i) => (
              <span key={i} css={lineMask}>
                <motion.span
                  css={{ display: "block" }}
                  initial={{ y: "105%" }}
                  animate={{ y: 0 }}
                  transition={{ delay: 0.15 + i * 0.1, duration: 1, ease: EASE }}
                >
                  {line}
                </motion.span>
              </span>
            ))}
          </span>
        </h1>
      </motion.div>

      <motion.a href="#top" css={cue} onClick={onAnchorClick("top")} style={{ opacity }}>
        <span>스크롤</span>
        <motion.span
          aria-hidden
          animate={{ y: [0, 6, 0] }}
          transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
        >
          ↓
        </motion.span>
      </motion.a>

      <CursorDot area={ref} />
    </section>
  );
};

export default Landing;

const landing = css`
  position: relative;
  min-height: calc(100svh - 63px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
  /* 클릭으로 파동을 만들 때 글자가 드래그·선택되지 않게 한다 */
  user-select: none;
  -webkit-user-select: none;
  /* 마우스를 쓰는 환경에서는 기본 커서를 숨기고 따라다니는 점(CursorDot)이 대신한다.
     점이 나타나지 않는 터치 기기·모션 줄이기 설정에서는 기본 커서를 그대로 둔다 */
  @media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
    &,
    & * {
      cursor: none;
    }
  }
`;

const backdrop = css`
  position: absolute;
  inset: 0;
`;

const inner = css`
  ${column};
  position: relative;
  padding-bottom: 64px;
`;

/* 제목 위에 붙는 라벨이 아니라 제목과 같은 크기 계열의 한 줄 소개 */
const eyebrowless = css`
  font-size: var(--step-lead);
  font-weight: 600;
  color: var(--muted);
`;

const headline = css`
  margin-top: 20px;
  font-size: clamp(2.5rem, 1rem + 6vw, 4.5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.12;
`;

const lineMask = css`
  display: block;
  overflow: hidden;
  padding-bottom: 0.08em;
`;

const rotator = css`
  display: inline-block;
  color: var(--accent);
`;

const charMask = css`
  display: inline-block;
  overflow: hidden;
  vertical-align: top;
  padding-bottom: 0.08em;
`;

const cue = css`
  position: absolute;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  font-size: var(--step-small);
  color: var(--muted);
  text-decoration: none;
  &:hover {
    color: var(--ink);
  }
`;

const srOnly = css`
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
`;
