/** @jsxImportSource @emotion/react */
import { RefObject, useEffect, useRef, useState } from "react";
import { css } from "@emotion/react";
import {
  motion,
  useAnimationControls,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  useVelocity,
} from "motion/react";

const FOLLOW = { stiffness: 500, damping: 40, mass: 0.6 };
// 늘어남에 탄성을 약하게 걸어, 멈추면 살짝 눌렸다가 출렁이며 동그랗게 돌아온다
const JELLY = { stiffness: 320, damping: 11, mass: 0.5 };
const MAX_STRETCH = 1.9; // 가장 빠를 때 진행 방향으로 늘어나는 배율
const FULL_SPEED = 2600; // 이 속도(px/s)에서 최대로 늘어난다
const HOLD_BELOW = 60; // 이보다 느리면 방향을 새로 정하지 않는다(멈출 때 흔들림 방지)

/**
 * 영역 안에서 마우스를 살짝 늦게 따라다니는 오렌지 점. 움직이면 진행 방향으로 쫀득하게 늘어나고,
 * 클릭하면 꾹 눌리듯 작아졌다 돌아온다. 글자 위에서도 보이도록 콘텐츠보다 위에 그리고,
 * 클릭은 그대로 아래로 통과시킨다.
 */
const CursorDot = ({ area }: { area: RefObject<HTMLElement> }) => {
  const reduce = useReducedMotion();
  const [inside, setInside] = useState(false);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const springX = useSpring(x, FOLLOW);
  const springY = useSpring(y, FOLLOW);
  const press = useAnimationControls();

  const vx = useVelocity(springX);
  const vy = useVelocity(springY);
  const speed = useTransform(() => Math.hypot(vx.get(), vy.get()));
  const stretch = useSpring(useTransform(speed, [0, FULL_SPEED], [1, MAX_STRETCH], { clamp: true }), JELLY);
  // 옆으로는 얇아져 면적이 거의 그대로 유지된다
  const squash = useTransform(stretch, (s) => 1 / Math.sqrt(Math.max(s, 0.5)));
  const lastAngle = useRef(0);
  const angle = useTransform(() => {
    if (speed.get() > HOLD_BELOW) lastAngle.current = (Math.atan2(vy.get(), vx.get()) * 180) / Math.PI;
    return lastAngle.current;
  });

  useEffect(() => {
    if (reduce) return;
    const locate = (e: PointerEvent) => {
      const el = area.current;
      if (!el || e.pointerType !== "mouse") return null;
      const rect = el.getBoundingClientRect();
      const px = e.clientX - rect.left;
      const py = e.clientY - rect.top;
      return px >= 0 && py >= 0 && px <= rect.width && py <= rect.height ? { px, py } : null;
    };

    const onMove = (e: PointerEvent) => {
      const hit = locate(e);
      setInside(!!hit);
      if (!hit) return;
      x.set(hit.px);
      y.set(hit.py);
    };
    const onDown = (e: PointerEvent) => {
      if (!locate(e)) return;
      press.start({ scale: [1, 0.5, 1.25, 1], transition: { duration: 0.45, times: [0, 0.2, 0.6, 1] } });
    };
    const onLeave = () => setInside(false);

    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerdown", onDown, { passive: true });
    document.documentElement.addEventListener("mouseleave", onLeave);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerdown", onDown);
      document.documentElement.removeEventListener("mouseleave", onLeave);
    };
  }, [area, reduce, x, y, press]);

  if (reduce) return null;

  return (
    <motion.div aria-hidden css={follower} style={{ x: springX, y: springY }}>
      <motion.span
        css={dot}
        animate={{ opacity: inside ? 1 : 0, scale: inside ? 1 : 0.4 }}
        transition={{ duration: 0.25 }}
      >
        {/* 먼저 진행 방향으로 돌려 놓고, 그 방향을 기준으로 늘린다 */}
        <motion.span css={fill} style={{ rotate: angle }}>
          <motion.span css={fill} style={{ scaleX: stretch, scaleY: squash }}>
            <motion.span css={core} animate={press} />
          </motion.span>
        </motion.span>
      </motion.span>
    </motion.div>
  );
};

export default CursorDot;

const follower = css`
  position: absolute;
  top: 0;
  left: 0;
  z-index: 2;
  pointer-events: none;
`;

/* 커서 끝이 점의 한가운데에 오도록 반지름만큼 당긴다 */
const dot = css`
  display: block;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
`;

const fill = css`
  display: block;
  width: 100%;
  height: 100%;
`;

const core = css`
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--accent);
`;
